referenceFixTemplate:
#include <iostream>
#include <string>
using namespace std;

class Animal {
protected:
    string name;
public:
    Animal(string n) : name(n) {}
    virtual void speak() const = 0;
};

class Cat : public Animal {
public:
    Cat(string n) : Animal(n) {}
    void speak() const override {
        cout << name << "：喵～" << endl;
    }
};

int main() {
    Cat c("{catName}");
    Animal& r = c;
    r.speak();
    return 0;
}
